var e=[{id:`muscle-building-nutrition`,title:"Eating to build muscle",icon:`dumbbell`,summary:"Muscle builds most easily with a small calorie surplus, plenty of protein and consistent training.",points:["A small surplus of about 5 to 10% above maintenance limits unnecessary fat gain","If you've trained for a while, aim to gain about 0.25 to 0.5% of your body weight per month","Eat protein and carbohydrates around your training to fuel it"]},{id:`fat-loss-nutrition`,title:"Eating to lose fat",icon:`flame`,summary:"Fat loss needs a calorie deficit you keep up over time, while protein and training protect your muscle.",points:["Aim to lose about 0.5 to 1% of your body weight per week","Keep protein high, and fill your meals with vegetables for volume and fibre","On a long diet, plan diet breaks or maintenance phases"]},{id:`macronutrients`,title:"Macronutrients explained",icon:`pie`,summary:"Protein, carbohydrates and fat each do a different job. Total calories decide whether your weight changes; macros shape your body composition and performance.",points:["Protein: 4 kcal per gram. Builds and repairs muscle.","Carbohydrates: 4 kcal per gram. The main fuel for hard training.","Fat: 9 kcal per gram. Needed for hormones and for absorbing fat-soluble vitamins."]},{id:`protein`,title:"Protein",icon:`egg`,summary:"The most important macronutrient for people who lift. Most people do well with 1.6 to 2.2 g per kg of body weight.",points:["Spread it over 3 to 5 meals","Include a good protein source in every meal","Eating more protein helps keep muscle while in a deficit"]},{id:`carbohydrates`,title:"Carbohydrates",icon:`wheat`,summary:"Carbohydrates fuel hard training and help you recover between sessions.",points:["Choose minimally processed sources: oats, rice, potatoes, fruit, wholegrains","Eat a bigger share of your carbohydrates around your training","Fibre helps digestion and keeps you full"]},{id:`fats`,title:"Fat",icon:`droplet`,summary:"Fat in your diet supports your hormones. A common range is 20 to 35% of your total calories.",points:["Eat oily fish, nuts, seeds, olive oil and avocado","Don't keep your fat intake extremely low for long periods","Fat is calorie-dense, so watch portions while dieting"]},{id:`meal-planning`,title:"Planning meals",icon:`calendar`,summary:"A simple meal structure you repeat makes consistency much easier than relying on willpower.",points:["Build each meal around protein, then add vegetables, carbohydrates and fat","Batch-cook basics two or three times a week","Keep easy high-protein options at hand for busy days"]},{id:`healthy-food-choices`,title:"Healthy food choices",icon:`leaf`,summary:"Most of what you eat should be whole, minimally processed food, with room for food you enjoy.",points:["Eat a variety of colourful fruit and vegetables every day","Choose lean protein and wholegrains most of the time","Some flexibility makes it easier to keep going for years"]},{id:`hydration`,title:"Drinking enough",icon:`droplet`,summary:"Even mild dehydration can make your training worse. You need more when you're bigger, it's hot or you sweat a lot.",points:["Drink regularly throughout the day","Pale yellow urine is a simple, practical sign","Replace fluids and salts after long or hot sessions"]},{id:`supplements`,title:"About supplements",icon:`capsule`,summary:"Supplements are optional. They can support a good diet, never replace it, and they are not medicine.",points:["Well-researched options include creatine monohydrate, protein powder, caffeine and vitamin D (if you're low)","Look for products tested by an independent lab","Talk to a healthcare professional first if you have a medical condition or take medication"]},{id:`recovery-and-sleep`,title:"Recovery and sleep",icon:`moon`,summary:"Your body repairs and adapts while you sleep. Poor sleep makes appetite, training and recovery harder.",points:["Aim for 7 to 9 hours a night","Go to bed and get up at similar times","Manage stress: it affects recovery as much as training does"]}];var o="This is general information, not personal medical or dietary advice. Talk to a doctor or registered dietitian before making big changes to what you eat, especially if you're pregnant, have a medical condition or take medication.";export{o as n,e as t};